ROLE_CODES = ("client", "contractor", "consultant")


def create_roles_and_assign_clients(apps, schema_editor):
    database = schema_editor.connection.alias
    User = apps.get_model("accounts", "User")
    Role = apps.get_model("accounts", "Role")
    roles = {
        code: Role.objects.using(database).get_or_create(code=code)[0]
        for code in ROLE_CODES
    }

    through = User.roles.through
    client_role = roles["client"]
    batch = []
    user_ids = User.objects.using(database).values_list("pk", flat=True)
    for user_id in user_ids.iterator(chunk_size=1000):
        batch.append(through(user_id=user_id, role_id=client_role.pk))
        if len(batch) == 1000:
            through.objects.using(database).bulk_create(batch, ignore_conflicts=True)
            batch = []
    if batch:
        through.objects.using(database).bulk_create(batch, ignore_conflicts=True)


